# Let me try to identify connected components of 9s
grid = [
    [9, 9, 0],
    [9, 9, 0],
    [9, 9, 0],
    [9, 0, 9],
    [9, 9, 0],
    [9, 0, 9],
    [0, 9, 9],
    [0, 9, 9]
]

def find_components(grid):
    """Find connected components using 4-connectivity"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    def dfs(r, c, comp_id):
        stack = [(r, c)]
        while stack:
            curr_r, curr_c = stack.pop()
            if visited[curr_r][curr_c]:
                continue
            visited[curr_r][curr_c] = True
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr][nc] and grid[nr][nc] == 9:
                        stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and not visited[r][c]:
                dfs(r, c, len(components))

    return components, visited

components, visited = find_components(grid)
print(f"Number of connected components of 9s: {len(components)}")
for i, comp in enumerate(components):
    coords = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if visited[r][c]:
                coords.append((r,c))
    print(f"Component {i}: {coords}")

